// Conceptual DPDK-style RX loop. Real code initializes EAL, ports, mempools.
#include <cstdint>
struct mbuf; // packet buffer mapped into user space (no copy)

extern uint16_t rx_burst(uint16_t port, uint16_t queue, mbuf** bufs, uint16_t n);
extern void     free_burst(mbuf** bufs, uint16_t n);
extern const uint8_t* payload(mbuf*, uint16_t* len);

void feed_handler(uint16_t port, uint16_t queue) {
    constexpr uint16_t BURST = 32;
    mbuf* bufs[BURST];
    for (;;) {                                   // busy-poll on a pinned core
        uint16_t n = rx_burst(port, queue, bufs, BURST);  // 0 if nothing yet
        for (uint16_t i = 0; i < n; ++i) {
            uint16_t len; const uint8_t* p = payload(bufs[i], &len);
            decode_market_data(p, len);          // your own parser + sequencing
        }
        if (n) free_burst(bufs, n);
        // no interrupt, no syscall, no copy: just spin and process bursts
    }
}
